def parsear_duracion(s):
    horas = minutos = 0
    for token in s.split():
        if token.endswith('h'):
            horas += int(token[:-1])
        elif token.endswith('m'):
            minutos += int(token[:-1])
    return horas * 60 + minutos

def es_palindromo(s):
    limpia = ''.join(c.lower() for c in s if c.isalnum())
    return limpia == limpia[::-1]

def aplanar(lista):
