def a_romano(n):
    tabla = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")
    ]
    resultado = ""
    for valor, simbolo in tabla:
        while n >= valor:
            resultado += simbolo
            n -= valor
    return resultado

def desde_romano(s):
    valores = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    anterior = 0
    for char in reversed(s):
        valor = valores[char]
        if valor < anterior:
            total -= valor
        else:
            total += valor
            anterior = valor
    return total

