def primos(n):
    if n < 2:
        return []
    primos_ = [2]
    for num in range(3, n + 1, 2):
        es_primo = True
        for p in primos_:
            if p * p > num:
                break
            if num % p == 0:
                es_primo = False
                break
        if es_primo:
            primos_.append(num)
    return primos_

