def binaria(lista, x):
    bajo = 0
    alto = len(lista) - 1

    while bajo <= alto:
        medio = (bajo + alto) // 2

        if lista[medio] == x:
            return medio
        elif lista[medio] < x:
            bajo = medio + 1
        else:
            alto = medio - 1

    return -1

