def contar_islas(grid):
    if not grid:
        return 0
    filas, cols = len(grid), len(grid[0])
    contadores = 0
    for i in range(filas):
        for j in range(cols):
            if grid[i][j] == 1:
                contadores += 1
                grid[i][j] = 0
                pila = [(i, j)]
                while pila:
                    x, y = pila.pop()
                    for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < filas and 0 <= ny < cols and grid[nx][ny] == 1:
                            grid[nx][ny] = 0
                            pila.append((nx, ny))
    return contadores

def distancia(a, b):
    n, m = len(a), len(b)
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = i
    for j in range(m + 1):
        dp[0][j] = j
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            costo = 1 if a[i - 1] != b[j - 1] else 0
            dp[i][j] = min(
                dp[i - 1][j] + 1,
                dp[i][j - 1] + 1,
                dp[i - 1][j - 1] + costo,
            )
    return dp[n][m]

