        len(p) >= 8
        and any(c.isupper() for c in p)
        and any(c.islower() for c in p)
        and any(c.isdigit() for c in p)
        and any(not c.isalnum() for c in p)
    )

def a_base(n, base):
    if n == 0:
        return '0'
    digits = '0123456789abcdef'
    result = ''
    while n > 0:
        result = digits[n % base] + result
        n //= base
    return result

