def titular(s):
    palabras = s.split()
    minusculas = {'de', 'del', 'la', 'las', 'el', 'los', 'y'}
    for i, palabra in enumerate(palabras):
        if i == 0:
            palabras[i] = palabra.capitalize()
        elif palabra.lower() not in minusculas:
            palabras[i] = palabra.capitalize()
    return ' '.join(palabras)

